import{_ as o,o as a,c as s,ag as i}from"./chunks/framework.BwSLX4ak.js";const h=JSON.parse('{"title":"Kugou","description":"","frontmatter":{},"headers":[],"relativePath":"en/allmusic/kugou.md","filePath":"en/allmusic/kugou.md"}'),t={name:"en/allmusic/kugou.md"};function r(l,e,c,d,u,n){return a(),s("div",null,[...e[0]||(e[0]=[i('<h1 id="kugou" tabindex="-1">Kugou <a class="header-anchor" href="#kugou" aria-label="Permalink to &quot;Kugou&quot;">​</a></h1><p>AllMusic_Kugou uses the API ID <code>kugou</code>. It supports Kugou keyword search, song information, covers, timed lyrics, and available playback URLs returned by the platform. It can extract song or playlist identifiers from some share links.</p><h2 id="search-and-default-source" tabindex="-1">Search and default source <a class="header-anchor" href="#search-and-default-source" aria-label="Permalink to &quot;Search and default source&quot;">​</a></h2><p>After following the <a href="./#installation">installation steps</a>:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/music search kugou 稻香</span></span></code></pre></div><p>Omit the API ID when AllMusic&#39;s <code>defaultApi</code> is <code>kugou</code>. Kugou songs commonly use a 32-character hexadecimal <code>hash</code>; playlists use numeric IDs. The implementation recognizes <code>hash</code>, <code>specialid</code> / <code>special_id</code> parameters and supported playlist paths. Link parameters <code>album_id</code> and <code>album_audio_id</code> are retained for song resolution.</p><h2 id="cookie-sources" tabindex="-1">Cookie sources <a class="header-anchor" href="#cookie-sources" aria-label="Permalink to &quot;Cookie sources&quot;">​</a></h2><p>By default, Kugou uses AllMusic&#39;s loaded <code>cookie.json</code>. It also supports a separate cookie, selected in this order:</p><ol><li>JVM system property <code>allmusic.kugou.cookie</code>.</li><li>Environment variable <code>ALLMUSIC_KUGOU_COOKIE</code>.</li><li>The source-code cookie override, normally empty.</li><li>AllMusic&#39;s cookie list when no override is present.</li></ol><p>A separate cookie helps when using different music platforms together. Manage real values through your service startup configuration. Restart the server or proxy after changing environment variables. Cookie validity, playable songs, and required device fields depend on Kugou&#39;s responses. If <code>mid</code> / <code>dfid</code> required by Android playback are missing, the log asks you to export cookies again.</p><p>The extension&#39;s <code>reload(File)</code> has no separate configuration-file logic. <code>KugouSong.debug</code> currently defaults to <code>false</code>; older README claims that it is enabled by default do not apply.</p><h2 id="build-from-source" tabindex="-1">Build from source <a class="header-anchor" href="#build-from-source" aria-label="Permalink to &quot;Build from source&quot;">​</a></h2><p>Put the core JAR matching your AllMusic version in <code>libs/</code>, then run:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gradlew.bat build</span></span></code></pre></div><p>On Linux/macOS, use <code>./gradlew build</code>. Output is in <code>build/libs/</code>, with the version from <code>build.gradle</code>. AllMusic must supply the core and shared libraries at runtime.</p><p><a href="https://github.com/hutuyee/AllMusic_Kugou" target="_blank" rel="noreferrer">Kugou source</a> · <a href="./troubleshooting.html">Troubleshooting</a></p>',16)])])}const g=o(t,[["render",r]]);export{h as __pageData,g as default};
